214	                        continue;
215	                    }
216	                    numDiscarded += srcset.droppedCandidates;
217	                    value = srcset.value;
218	                } else if (SizesCleaner.isSizes(key) && isResponsiveImage(sourceTag)) {
219	                    // validate and rewrite each size entry instead of keeping the opaque media/length list
