8	/**
9	 Validates and rewrites {@code sizes} attributes, one size entry at a time, so the browser receives trustworthy
10	 candidates without widening the element's security boundary.
11	 <p>
12	 The attribute value is a comma-separated list of size entries. Entries are split on top-level commas only: a comma
13	 nested inside a balanced pair of parentheses (a media condition, or a {@code calc()} length) belongs to the entry
14	 that opened the parentheses. Each entry has an optional media condition followed by a required length value:
15	 </p>
16	 <ul>
17	 <li>an optional media condition is a non-empty, parenthesis-balanced expression containing only
18	     letters, digits, whitespace, hyphens, colons, dots, comparison characters ({@code < = >}), and nested
19	     parentheses; it need not be wrapped in an outer parenthesized group, so a bare media type such as
20	     {@code screen} is acceptable. A semicolon, brace, quote, control character, or any other character invalidates
21	     the entry;</li>
22	 <li>the length is either a zero or a non-negative decimal number immediately followed by one of
23	     {@code px, em, rem, vw, vh, vmin, vmax, ch, ex, %} (e.g. {@code 100vw}, {@code 0px}, {@code 1.5em}), or a
24	     balanced {@code calc()} expression whose body contains only digits, dots, whitespace, the {@code + - * /}
25	     operators, nested parentheses, and the listed units. A URL, a semicolon, a brace, a leading minus, an empty
26	     length, or an unbalanced parenthesis invalidates the entry.</li>
27	 </ul>
28	 <p>
29	 A matching {@code "} or {@code '} pair wrapping the whole value delimits it in the source markup (character
30	 references have already been decoded by the parser); the delimiting quotes are syntax only and never appear in the
31	 cleaned output. One malformed entry is dropped on its own and never swallows a following valid entry: after an
32	 unbalanced parenthesis, parsing resynchronizes at the next comma. Accepted entries are trimmed and joined in input
33	 order with a stable {@code ", "} separator; a surviving entry with the exact same trimmed spelling as an earlier
34	 survivor is emitted only once, at its first position, so re-cleaning is stable. When no entry
35	 survives, the attribute must be removed rather than left empty.
36	 </p>
37	 */
38	final class SizesCleaner {
39	    private SizesCleaner() {}
40	
41	    /**
42	     Determine whether the supplied attribute key is a {@code sizes} attribute that should be handled entry by entry,
43	     rather than treated as an ordinary opaque attribute.
44	     @param key the attribute key to test
45	     @return true if it is a {@code sizes} attribute
46	     */
47	    static boolean isSizes(String key) {
48	        return "sizes".equalsIgnoreCase(key);
49	    }
50	
51	    /**
52	     Clean a {@code sizes} attribute value into a value containing only the acceptable entries, in their original
53	     order. The input is never modified; callers must apply the result themselves.
54	     @param rawValue the original attribute value
55	     @return the cleaning result; {@link Result#removed} is true (with a null value) when no entry survived, in which
56	     case the attribute must be removed rather than left empty
57	     */
58	    static Result clean(String rawValue) {
59	        List<String> accepted = new ArrayList<>();
60	        int dropped = 0;
61	        if (rawValue != null && !rawValue.isEmpty()) {
62	            String value = stripQuotes(rawValue.trim()); // a quote pair wrapping the whole attribute value
63	            int len = value.length();
64	            int pos = 0;
65	
66	            while (pos < len) {
67	                // Splitting loop: collect one entry. Commas separate entries only at depth zero; a comma inside a
68	                // balanced parenthesized region is entry content. An unmatched ')' ends the entry at that point (the
69	                // entry is rejected); an unmatched '(' would otherwise run to the end, so the first comma inside it
70	                // is remembered and used as a resync point when the group never closes, so a following valid entry
71	                // is not swallowed.
72	                int entryStart = pos;
73	                int depth = 0;
74	                int deepComma = -1;
75	                boolean strayClose = false;
76	                while (pos < len) {
77	                    char c = value.charAt(pos);
78	                    if (c == '(') {
79	                        depth++;
80	                    } else if (c == ')') {
81	                        depth--;
82	                        if (depth < 0) strayClose = true;
83	                    } else if (c == ',') {
84	                        if (depth <= 0) break; // top-level separator
85	                        if (deepComma < 0) deepComma = pos; // first separator inside an unclosed group
86	                    }
87	                    pos++;
88	                }
89	
90	                String entry;
91	                if (pos >= len && depth > 0 && deepComma >= 0) {
92	                    // the group never closed: reject the run up to its first inner comma, and reparse every later
93	                    // comma-separated chunk as its own entry, so a trailing legal entry is not swallowed
94	                    entry = value.substring(entryStart, deepComma);
95	                    pos = deepComma;
96	                } else {
97	                    entry = value.substring(entryStart, pos);
98	                }
99	                boolean balanced = depth == 0 && !strayClose;
100	
101	                String normalized = validateEntry(entry, balanced);
102	                if (normalized != null) {
103	                    // the cleaned value never carries a repeated entry: when the same spelling survives twice it
104	                    // is emitted once, at its first position, so re-cleaning is stable
105	                    if (accepted.contains(normalized)) dropped++;
106	                    else accepted.add(normalized);
107	                } else if (!entry.trim().isEmpty() || !balanced) dropped++;
108	
109	                if (pos < len && value.charAt(pos) == ',') pos++; // consume the separator
110	            }
111	        }
112	
113	        if (accepted.isEmpty()) return new Result(null, dropped, true);
114	        return new Result(join(accepted), dropped, false);
115	    }
116	
117	    /** The outcome of cleaning a sizes attribute: the rewritten {@code value} (or null) and statistics. */
118	    static final class Result {
119	        final String value;
120	        final int droppedEntries;
121	        final boolean removed;
122	
123	        private Result(String value, int droppedEntries, boolean removed) {
124	            this.value = value;
125	            this.droppedEntries = droppedEntries;
126	            this.removed = removed;
127	        }
128	    }
129	
130	    /**
131	     Validate one raw entry and return its trimmed spelling, or {@code null} when it is malformed. {@code balanced}
132	     reports whether the collected run ended at parenthesis depth zero; an unbalanced run can never be a valid media
133	     condition or length.
134	     <p>
135	     A media condition may span several parenthesized groups joined by keywords ({@code (min-width: 30em) and
136	     (orientation: landscape)}), so the length is located at the end of the entry: either a whitespace-free scalar
137	     suffix, or a balanced {@code calc(...)} group. Anything before it is the optional media condition.
138	     </p>
139	     */
140	    private static String validateEntry(String entry, boolean balanced) {
141	        String trimmed = stripQuotes(entry.trim()); // a quote pair delimiting this single entry
142	        if (trimmed.isEmpty() || !balanced) return null;
143	        if (containsUnsafeChar(trimmed)) return null;
144	        if (containsScriptFragment(trimmed)) return null;
145	
146	        int lengthStart = findLengthStart(trimmed);
147	        if (lengthStart < 0) return null;
148	
149	        String length = trimmed.substring(lengthStart).trim();
150	        if (!isValidLength(length)) return null;
151	
152	        if (lengthStart > 0) {
153	            String condition = trimmed.substring(0, lengthStart);
154	            // the condition and the length must be separated by whitespace
155	            if (!StringUtil.isWhitespace(condition.charAt(condition.length() - 1))) return null;
156	            if (!isValidMediaCondition(condition.trim())) return null;
157	        }
158	        return trimmed;
159	    }
160	
161	    /**
162	     Return the index at which the trailing length begins, or {@code -1} when the entry does not end in a recognizable
163	     length. A {@code calc(...)} length ends in a balanced {@code )} whose matching {@code (} is preceded by the word
164	     {@code calc} at a token boundary; any other ending must be a single whitespace-free scalar token.
165	     */
166	    private static int findLengthStart(String s) {
167	        int n = s.length();
168	        if (s.charAt(n - 1) == ')') {
169	            int depth = 0;
170	            int i = n - 1;
171	            do {
172	                char c = s.charAt(i);
173	                if (c == ')') depth++;
174	                else if (c == '(') depth--;
175	                i--;
176	            } while (i >= 0 && depth > 0);
177	            int open = i + 1; // index of the matching '('
178	            int wordStart = open;
179	            while (wordStart > 0 && isAsciiLetter(s.charAt(wordStart - 1))) wordStart--;
180	            if (open - wordStart == 4 && s.regionMatches(true, wordStart, "calc", 0, 4)
181	                && (wordStart == 0 || StringUtil.isWhitespace(s.charAt(wordStart - 1)))) {
182	                return wordStart;
183	            }
184	        }
185	        int ws = s.length() - 1;
186	        while (ws >= 0 && !StringUtil.isWhitespace(s.charAt(ws))) ws--;
187	        return ws + 1;
188	    }
189	
190	    /**
191	     Validate the media condition text. It must hold a substantive token (a non-whitespace character other than a
192	     parenthesis), only the permitted media-query characters, and have balanced nested parentheses; it need not be
193	     wrapped in an outer parenthesized group, so a bare media type such as {@code screen} is acceptable, while an
194	     empty {@code ()} group is not a condition. No semicolons, braces, quotes, or other punctuation that could carry
195	     stylesheet or script content; a script scheme smuggled in with whitespace inside its name is also rejected.
196	     */
197	    private static boolean isValidMediaCondition(String condition) {
198	        String s = condition.trim();
199	        if (s.isEmpty()) return false;
200	        int depth = 0;
201	        boolean hasToken = false;
202	        for (int i = 0; i < s.length(); i++) {
203	            char c = s.charAt(i);
204	            if (c == '(') {
205	                depth++;
206	            } else if (c == ')') {
207	                depth--;
208	                if (depth < 0) return false;
209	            } else if (!isMediaConditionChar(c)) {
210	                return false;
211	            } else if (!StringUtil.isWhitespace(c)) {
212	                hasToken = true; // an empty () or ( ) group is not a media condition
213	            }
214	        }
215	        return depth == 0 && hasToken;
216	    }
217	
218	    private static boolean isMediaConditionChar(char c) {
219	        if (c >= 'a' && c <= 'z') return true;
220	        if (c >= 'A' && c <= 'Z') return true;
221	        if (c >= '0' && c <= '9') return true;
222	        return c == '-' || c == ':' || c == '.' || c == '<' || c == '>' || c == '='
223	            || StringUtil.isWhitespace(c);
224	    }
225	
226	    /**
227	     Validate the length token: either a plain non-negative decimal scalar followed by a recognized length unit, or a
228	     balanced {@code calc()} expression over those same scalars and units.
229	     */
230	    private static boolean isValidLength(String s) {
231	        if (s.isEmpty()) return false;
232	        if (isAsciiLetter(s.charAt(0))) {
233	            // only a calc(...) expression may lead with a letter; any other word (url, expression, attr, ...) is out
234	            if (!startsWithCalc(s)) return false;
235	            if (s.charAt(s.length() - 1) != ')') return false;
236	            return isValidCalcBody(s.substring(5, s.length() - 1));
237	        }
238	        return isScalarLength(s);
239	    }
240	
241	    private static boolean startsWithCalc(String s) {
242	        return s.length() > 5 && s.regionMatches(true, 0, "calc(", 0, 5);
243	    }
244	
245	    /**
246	     Validate the body of a {@code calc()} expression: balanced parentheses, and only non-negative scalars with
247	     recognized units (or bare numbers) joined by the {@code + - * /} operators. There is no leading minus, no empty
248	     operand, no URL, no semicolon, and no brace.
249	     */
250	    private static boolean isValidCalcBody(String body) {
251	        String s = body.trim();
252	        if (s.isEmpty()) return false;
253	        char first = s.charAt(0);
254	        if (first == '-' || first == '+' || first == '*' || first == '/') return false;
255	
256	        int depth = 0;
257	        int i = 0;
258	        int n = s.length();
259	        boolean prevOperand = false; // the previous token was a scalar or ')', so an operator may come next
260	        while (i < n) {
261	            char c = s.charAt(i);
262	            if (StringUtil.isWhitespace(c)) { i++; continue; }
263	            if (c == '(') {
264	                if (prevOperand) return false; // an operand must be followed by an operator, not a group
265	                depth++;
266	                i++;
267	                continue;
268	            }
269	            if (c == ')') {
270	                depth--;
271	                if (depth < 0 || !prevOperand) return false; // empty group or unbalanced close
272	                i++;
273	                continue;
274	            }
275	            if (c == '+' || c == '-' || c == '*' || c == '/') {
276	                if (!prevOperand) return false; // missing left operand (also rejects doubled operators)
277	                prevOperand = false;
278	                i++;
279	                continue;
280	            }
281	            if (isAsciiLetter(c)) {
282	                // the only word legal at an operand position is a nested calc(...): a balanced group over the same
283	                // grammar. Any other word (url, expression, attr, an unknown unit spelling, ...) is rejected.
284	                if (!s.regionMatches(true, i, "calc(", 0, 5)) return false;
285	                int close = matchingClose(s, i + 5);
286	                if (close < 0 || !isValidCalcBody(s.substring(i + 5, close))) return false;
287	                i = close + 1;
288	                if (i < n) {
289	                    char next = s.charAt(i);
290	                    if (!StringUtil.isWhitespace(next) && next != '+' && next != '-' && next != '*'
291	                        && next != '/' && next != ')') return false;
292	                }
293	                prevOperand = true;
294	                continue;
295	            }
296	            // otherwise a scalar operand: a non-negative number with an optional recognized unit
297	            int numEnd = readNumber(s, i);
298	            if (numEnd == i) return false;
299	            int afterUnit = readUnit(s, numEnd);
300	            if (afterUnit != numEnd) {
301	                i = afterUnit; // a unit followed the number
302	            } else {
303	                i = numEnd; // bare number (legal inside calc), but never a bare word or unknown unit
304	                if (i < n && isAsciiLetter(s.charAt(i))) return false;
305	            }
306	            // the operand must end at whitespace, an operator, a parenthesis, or the end of the body
307	            if (i < n) {
308	                char next = s.charAt(i);
309	                if (!StringUtil.isWhitespace(next) && next != '+' && next != '-' && next != '*'
310	                    && next != '/' && next != ')') return false;
311	            }
312	            prevOperand = true;
313	        }
314	        return depth == 0 && prevOperand;
315	    }
316	
317	    /** Read a non-negative decimal number ({@code 0}, {@code 12}, {@code 1.5}, {@code .5}); no sign or exponent. */
318	    private static int readNumber(String s, int start) {
319	        int i = start;
320	        int n = s.length();
321	        int digits = 0;
322	        while (i < n && isAsciiDigit(s.charAt(i))) { digits++; i++; }
323	        if (i < n && s.charAt(i) == '.') {
324	            i++;
325	            int frac = 0;
326	            while (i < n && isAsciiDigit(s.charAt(i))) { frac++; i++; }
327	            if (frac == 0) return start; // a trailing or fraction-less dot is not a number
328	        } else if (digits == 0) {
329	            return start;
330	        }
331	        return i;
332	    }
333	
334	    /** Read a recognized length unit starting at {@code start}; return the index just past it, or {@code start}. */
335	    private static int readUnit(String s, int start) {
336	        int n = s.length();
337	        if (start < n && s.charAt(start) == '%') return start + 1;
338	        String[] units = {"vmin", "vmax", "rem", "vw", "vh", "em", "px", "ch", "ex"};
339	        for (String unit : units) {
340	            int end = start + unit.length();
341	            if (end <= n && s.regionMatches(true, start, unit, 0, unit.length())) return end;
342	        }
343	        return start;
344	    }
345	
346	    /** A plain scalar length: a non-negative decimal number immediately followed by a recognized unit. */
347	    private static boolean isScalarLength(String s) {
348	        int numEnd = readNumber(s, 0);
349	        if (numEnd == 0) return false;
350	        int unitEnd = readUnit(s, numEnd);
351	        return unitEnd != numEnd && unitEnd == s.length();
352	    }
353	
354	    /** Given the index just inside a {@code (} group, return the index of its matching {@code )}, or {@code -1}. */
355	    private static int matchingClose(String s, int start) {
356	        int depth = 1;
357	        for (int i = start; i < s.length(); i++) {
358	            char c = s.charAt(i);
359	            if (c == '(') depth++;
360	            else if (c == ')') {
361	                depth--;
362	                if (depth == 0) return i;
363	            }
364	        }
365	        return -1;
366	    }
367	
368	    private static boolean isAsciiDigit(char c) {
369	        return c >= '0' && c <= '9';
370	    }
371	
372	    private static boolean isAsciiLetter(char c) {
373	        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
374	    }
375	
376	    /**
377	     Reject characters that can never appear in a valid entry: control characters (other than HTML whitespace),
378	     quotes, semicolons, and braces. These are the characters that could smuggle stylesheet or script content through
379	     a length or media condition. Both the C0 range (and DEL) and the C1 range U+0080–U+009F count as control
380	     characters here.
381	     */
382	    private static boolean containsUnsafeChar(String s) {
383	        for (int i = 0; i < s.length(); i++) {
384	            char c = s.charAt(i);
385	            if (c == '"' || c == '\'' || c == ';' || c == '{' || c == '}') return true;
386	            if (c <= 0x1f && !StringUtil.isWhitespace(c)) return true;
387	            if (c == 0x7f || (c >= 0x80 && c <= 0x9f)) return true;
388	        }
389	        return false;
390	    }
391	
392	    /**
393	     Reject URL and script fragments that use only otherwise-permitted characters. A {@code url(} token is never
394	     valid in a media condition or length, and a script scheme name (optionally broken up by whitespace or an HTML
395	     entity-decoded tab, e.g. {@code java&Tab;script:}) must never survive. Whitespace is flattened before the
396	     substring test so spacing inside a scheme name cannot hide it.
397	     */
398	    private static boolean containsScriptFragment(String s) {
399	        String lc = s.toLowerCase();
400	        if (lc.contains("url(")) return true;
401	        String flattened = StringUtil.normaliseWhitespace(lc).replace(" ", "");
402	        return flattened.contains("javascript:") || flattened.contains("vbscript:")
403	            || flattened.contains("livescript:") || flattened.contains("data:");
404	    }
405	
406	    /**
407	     Strip a single pair of matching delimiting quotes wrapping the whole text. The delimiters are parse-time syntax
408	     only; they are removed only when the same quote does not also occur inside the text (that is per-entry quoting,
409	     handled entry by entry), and a quote anywhere else is left in place and rejected by entry validation rather than
410	     treated as syntax.
411	     */
412	    private static String stripQuotes(String s) {
413	        if (s.length() >= 2) {
414	            char first = s.charAt(0);
415	            char last = s.charAt(s.length() - 1);
416	            if ((first == '"' || first == '\'') && first == last
417	                && s.indexOf(first, 1) == s.length() - 1) {
418	                return s.substring(1, s.length() - 1);
419	            }
420	        }
421	        return s;
422	    }
423	
424	    private static String join(List<String> entries) {
425	        StringBuilder sb = StringUtil.borrowBuilder();
426	        for (int i = 0; i < entries.size(); i++) {
427	            if (i > 0) sb.append(", ");
428	            sb.append(entries.get(i));
429	        }
430	        return StringUtil.releaseBuilder(sb);
431	    }
432	}
